import{_ as i,o,c as t,ag as n}from"./chunks/framework.DqVSm8kp.js";const h=JSON.parse(`{"title":"Atelier d'Outils","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/tool-workshop.md","filePath":"fr/guide/tool-workshop.md"}`),r={name:"fr/guide/tool-workshop.md"};function s(a,e,l,d,u,c){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="atelier-d-outils" tabindex="-1">Atelier d&#39;Outils <a class="header-anchor" href="#atelier-d-outils" aria-label="Permalink to &quot;Atelier d&#39;Outils&quot;">​</a></h1><p>L&#39;Atelier d&#39;Outils est un canevas visuel pour creer, modifier et tester des definitions d&#39;outils que les modeles peuvent appeler pendant le chat.</p><p><strong>Element de la barre laterale :</strong> Atelier d&#39;Outils <strong>Route :</strong> <code>/tools</code></p><h2 id="vue-d-ensemble-de-l-interface" tabindex="-1">Vue d&#39;ensemble de l&#39;interface <a class="header-anchor" href="#vue-d-ensemble-de-l-interface" aria-label="Permalink to &quot;Vue d&#39;ensemble de l&#39;interface&quot;">​</a></h2><p>La page presente un <strong>canevas a base de noeuds</strong> propulse par Vue Flow. Chaque outil est represente sous forme de noeud visuel affichant son nom, sa description, ses parametres et le corps de son implementation.</p><h2 id="creer-des-outils" tabindex="-1">Creer des outils <a class="header-anchor" href="#creer-des-outils" aria-label="Permalink to &quot;Creer des outils&quot;">​</a></h2><h3 id="a-partir-de-modeles" tabindex="-1">A partir de modeles <a class="header-anchor" href="#a-partir-de-modeles" aria-label="Permalink to &quot;A partir de modeles&quot;">​</a></h3><p>Cliquez sur <strong>Modeles</strong> pour parcourir plus de 15 modeles integres, notamment :</p><ul><li>Requetes web (HTTP)</li><li>Calculatrice</li><li>Integration Google Calendar / Gmail</li><li>Testeur de regex</li><li>Utilitaires de date/heure</li><li>Et plus encore</li></ul><h3 id="a-partir-de-zero" tabindex="-1">A partir de zero <a class="header-anchor" href="#a-partir-de-zero" aria-label="Permalink to &quot;A partir de zero&quot;">​</a></h3><p>Cliquez sur <strong>Ajouter un outil</strong> pour creer un noeud d&#39;outil vierge. Remplissez :</p><ul><li><strong>Nom</strong> -- Le nom de la fonction (utilise par le modele)</li><li><strong>Description</strong> -- Ce que fait l&#39;outil (aide le modele a decider quand l&#39;utiliser)</li><li><strong>Parametres</strong> -- Entrees definies en JSON Schema</li><li><strong>Implementation</strong> -- Corps de la fonction TypeScript</li></ul><h2 id="modifier-les-outils" tabindex="-1">Modifier les outils <a class="header-anchor" href="#modifier-les-outils" aria-label="Permalink to &quot;Modifier les outils&quot;">​</a></h2><h3 id="edition-de-code-en-ligne" tabindex="-1">Edition de code en ligne <a class="header-anchor" href="#edition-de-code-en-ligne" aria-label="Permalink to &quot;Edition de code en ligne&quot;">​</a></h3><p>Chaque noeud d&#39;outil dispose d&#39;un editeur <strong>CodeMirror 6</strong> complet avec coloration syntaxique TypeScript. Modifiez l&#39;implementation directement sur le canevas.</p><h3 id="panneau-de-code-synchronisation-bidirectionnelle" tabindex="-1">Panneau de code (synchronisation bidirectionnelle) <a class="header-anchor" href="#panneau-de-code-synchronisation-bidirectionnelle" aria-label="Permalink to &quot;Panneau de code (synchronisation bidirectionnelle)&quot;">​</a></h3><p>Ouvrez le <strong>Panneau de code</strong> pour voir tous les outils sous forme de code source TypeScript combine. Cela utilise un <strong>analyseur AST Recast</strong> pour une synchronisation bidirectionnelle :</p><ul><li>Modification du code dans le panneau → les noeuds se mettent a jour sur le canevas</li><li>Modification des noeuds sur le canevas → le code se met a jour dans le panneau</li></ul><h3 id="visionneuse-de-schema" tabindex="-1">Visionneuse de schema <a class="header-anchor" href="#visionneuse-de-schema" aria-label="Permalink to &quot;Visionneuse de schema&quot;">​</a></h3><p>Cliquez sur l&#39;icone de schema sur n&#39;importe quel outil pour voir son <strong>schema JSON compatible OpenAI</strong> genere automatiquement. Copie en un clic pour utilisation dans d&#39;autres systemes.</p><h2 id="sonder-et-selectionner" tabindex="-1">Sonder et selectionner <a class="header-anchor" href="#sonder-et-selectionner" aria-label="Permalink to &quot;Sonder et selectionner&quot;">​</a></h2><p>Pointez vers n&#39;importe quelle URL d&#39;API pour :</p><ol><li><strong>Sonder</strong> le endpoint -- envoyer une requete et inspecter la reponse</li><li><strong>Parcourir l&#39;arborescence JSON</strong> -- developper/reduire la structure de la reponse</li><li><strong>Selectionner des champs</strong> -- choisir les donnees dont vous avez besoin</li><li><strong>Generer automatiquement</strong> le code fetch et les correspondances de parametres</li></ol><h2 id="decouverte-openapi" tabindex="-1">Decouverte OpenAPI <a class="header-anchor" href="#decouverte-openapi" aria-label="Permalink to &quot;Decouverte OpenAPI&quot;">​</a></h2><p>Si une API dispose d&#39;une specification OpenAPI/Swagger :</p><ol><li>Saisissez l&#39;URL de la specification</li><li>LLMxRay analyse la specification automatiquement</li><li>Parcourez les endpoints disponibles</li><li>Selectionnez un endpoint pour generer automatiquement une definition d&#39;outil</li></ol><h2 id="execution-en-direct" tabindex="-1">Execution en direct <a class="header-anchor" href="#execution-en-direct" aria-label="Permalink to &quot;Execution en direct&quot;">​</a></h2><p>Pendant le chat, lorsque le modele appelle un outil :</p><ul><li>Le noeud correspondant <strong>pulse</strong> sur le canevas</li><li>Les resultats d&#39;execution apparaissent en <strong>superposition</strong> sur le noeud</li><li>La chronologie des appels d&#39;outils (dans Diagnostics de Chat) renvoie vers le canevas</li></ul><h2 id="optimiseur-d-appels-d-outils" tabindex="-1">Optimiseur d&#39;appels d&#39;outils <a class="header-anchor" href="#optimiseur-d-appels-d-outils" aria-label="Permalink to &quot;Optimiseur d&#39;appels d&#39;outils&quot;">​</a></h2><p>Lorsqu&#39;un modele appelle un outil pendant le chat, un bouton <strong>&quot;Optimiser cet outil&quot;</strong> apparait sur le resultat. Cliquez dessus pour ouvrir le tiroir d&#39;optimisation des reponses :</p><ol><li><strong>Visualiser</strong> la reponse de l&#39;API sous forme d&#39;arborescence JSON interactive</li><li><strong>Selectionner</strong> uniquement les champs dont le modele a reellement besoin</li><li><strong>Generer automatiquement</strong> un code fetch optimise avec extraction des champs</li><li><strong>Creer</strong> un nouvel outil optimise dans l&#39;Atelier en un clic</li></ol><h2 id="persistance" tabindex="-1">Persistance <a class="header-anchor" href="#persistance" aria-label="Permalink to &quot;Persistance&quot;">​</a></h2><p>Les definitions d&#39;outils, positions des noeuds, correspondances et configurations de sondage sont toutes persistees et survivent aux actualisations du navigateur.</p><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li>Commencez par un modele et personnalisez-le -- c&#39;est plus rapide que de partir de zero.</li><li>Utilisez la <strong>Visionneuse de schema</strong> pour verifier que votre definition d&#39;outil correspond a ce que les modeles attendent.</li><li>Le flux de travail <strong>Sonder et selectionner</strong> est le moyen le plus rapide d&#39;encapsuler une API REST en tant qu&#39;outil.</li><li>Les outils sont automatiquement disponibles dans le chat lorsqu&#39;ils sont actives.</li></ul>',36)])])}const m=i(r,[["render",s]]);export{h as __pageData,m as default};
